function Capabilities({project,refresh}:{project:string;refresh:number}){const[data,setData]=useState<any>(),[error,setError]=useState('');useEffect(()=>{void api('/capabilities'+query(project)).then(setData).catch(e=>setError(e.message));},[project,refresh]);if(error)return <ErrorNotice error={error}/>;if(!data)return <Loading/>;const items=Array.isArray(data.items)?data.items:Array.isArray(data.capabilities)?data.capabilities:Object.entries(data).map(([name,value])=>typeof value==='object'?{name,...value as object}:{name,available:value});return <><div className="info-strip"><ShieldCheck size={18}/><p>配置、可用与验证分别记录。连接声明不会自动成为实际执行证明。</p></div><div className="capability-grid">{items.map((c:any,i:number)=><section className="panel capability-card" key={c.id||c.name||i}><div className="capability-heading"><span className="row-icon"><Terminal size={19}/></span><div><h3>{c.title||c.name||c.id}</h3><small>{c.provider||c.type||'运行能力'}</small></div></div><p>{c.description||c.reason||'该能力的状态由服务端提供。'}</p><div className="capability-states">{['configured','available','verified'].map((k,j)=><span key={k}><i className={c[k]?'yes':'no'}>{c[k]?<Check size={12}/>:<X size={12}/>}</i>{['已配置','可用','已验证'][j]}</span>)}</div>{c.detail&&<small className="muted">{c.detail}</small>}</section>)}</div>{!items.length&&<Empty title="暂无能力声明" description="配置真实运行适配器后，服务端会显示能力与验证状态。"/>}</>}
function ProjectSettings({project}:{project:RecordItem}){return <section className="panel settings-panel"><div className="panel-heading"><div><h2>项目信息</h2><p>当前项目的持久身份与上下文</p></div><Folder size={20}/></div><dl><dt>项目名称</dt><dd>{label(project)}</dd><dt>项目 ID</dt><dd><code>{project.id}</code></dd><dt>项目简介</dt><dd>{project.description||'尚未填写'}</dd><dt>记录版本</dt><dd>v{project.version||1}</dd></dl><p className="muted">项目内容、执行与访问权限均在此项目范围内隔离。</p></section>}
function KnowledgeSearch({project}:{project:string}){const[q,setQ]=useState(''),[results,setResults]=useState<any>(),[busy,setBusy]=useState(false),[error,setError]=useState('');return <section className="panel knowledge-search"><div className="panel-heading"><div><h2>搜索团队知识</h2><p>找到相关记录，并回到可追溯的来源。</p></div><Search size={22}/></div><form className="search-form" onSubmit={async e=>{e.preventDefault();setBusy(true);try{setResults(await api('/search',{project_id:project,query:q,types:[]}));setError('');}catch(err){setError((err as Error).message);}finally{setBusy(false);}}}><Search size={19}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="搜索需求、任务和文档内容…" required/><button className="primary" disabled={busy}>搜索</button></form>{error&&<ErrorNotice error={error}/>}<div className="search-results">{results?.items?.map((r:any)=><article key={r.id}><span className="type-chip">{r.type}</span><h3>{r.title}</h3><p>{r.snippet}</p><small>{r.source_ref} · 版本 {r.revision} · {typeof r.locator === 'object' ? JSON.stringify(r.locator) : r.locator}</small></article>)}</div>{results&&!results.items?.length&&<Empty title="没有找到匹配内容" description="尝试更短的关键词，或先添加项目文档。"/>}{results&&<p className="muted">检索方式：{results.mode} · 索引水位：{results.index_watermark||'未提供'}</p>}</section>}

function ProjectCounts({project,refresh}:{project:string;refresh:number}){const[counts,setCounts]=useState<Record<string,number>>();useEffect(()=>{let alive=true;setCounts(undefined);if(project)void api<{counts:Record<string,number>}>('/overview'+query(project)).then(data=>{if(alive)setCounts(data.counts);}).catch(()=>{});return()=>{alive=false;};},[project,refresh]);return counts?<div className="topbar-counts" aria-label={tr("shell.current_project_counts")}><span><Trans i18nKey="shell.count.requirements" values={{count:counts.requirements===undefined?'—':formatNumber(counts.requirements)}} components={{b:<b/>}}/></span><span><Trans i18nKey="shell.count.tasks" values={{count:counts.tasks===undefined?'—':formatNumber(counts.tasks)}} components={{b:<b/>}}/></span></div>:null;}
